var library=[{"id": 101, "title": "Master YouTube Strategy Principles", "category": "Research", "topic": "Strategy", "type": "Guide", "description": "The core operating principles for selecting topics, packaging videos, retaining viewers, and improving through evidence.", "tags": ["strategy", "audience", "growth"], "content": "\n<h3>Purpose</h3>\n<p>Use these principles as the benchmark for every video decision. They are not rigid rules; they are the strongest recurring patterns from the creator research synthesized for this operating system.</p>\n<h3>Core Principles</h3>\n<ul>\n<li><b>Package before production.</b> Clarify the topic, title direction, and thumbnail promise before scripting the full video.</li>\n<li><b>One video, one clear promise.</b> A viewer should understand the outcome or curiosity gap immediately.</li>\n<li><b>Specific beats broad.</b> Concrete problems, transformations, timeframes, and constraints are easier to click and remember.</li>\n<li><b>The opening must cash the click.</b> Confirm the promise quickly, show evidence, and remove unnecessary setup.</li>\n<li><b>Retention is designed.</b> Pacing, progress, visual change, tension, and unanswered questions keep attention.</li>\n<li><b>Every upload is an experiment.</b> Use performance to make one or two deliberate improvements—not to reinvent everything.</li>\n<li><b>Build for the right viewer.</b> Views from the wrong audience can weaken the channel’s direction.</li>\n<li><b>Systems create consistency.</b> Templates, SOPs, checklists, and post-publish reviews reduce decision fatigue.</li>\n</ul>\n<div class=\"callout\"><b>Creator OS standard:</b> Do not move an idea into full production until its audience, promise, title direction, thumbnail concept, and viewer payoff are clear.</div>\n", "related": [117]}, {"id": 102, "title": "Video Idea Validation Framework", "category": "Templates", "topic": "Ideas", "type": "Template", "description": "A practical scorecard for deciding whether an idea deserves production time before details are invented.", "tags": ["ideas", "marketability", "scorecard"], "content": "\n<h3>Use This Before Scripting</h3>\n<ol>\n<li><b>Audience:</b> Who specifically needs or wants this?</li>\n<li><b>Problem or desire:</b> What tension, pain, curiosity, or aspiration does it activate?</li>\n<li><b>Promise:</b> What will the viewer know, feel, avoid, or achieve?</li>\n<li><b>Distinctive angle:</b> Why this video instead of the dozens already available?</li>\n<li><b>Visual potential:</b> Can the result, contrast, process, or evidence be shown?</li>\n<li><b>Channel fit:</b> Does it reinforce “Come build an AI-powered life with me”?</li>\n<li><b>Credibility:</b> Can Carolynn demonstrate a real experience, result, experiment, or case study?</li>\n<li><b>Series potential:</b> Does this lead naturally to another video?</li>\n</ol>\n<h3>100-Point Score</h3>\n<ul>\n<li>Audience need or curiosity — 20</li>\n<li>Clarity of promise — 20</li>\n<li>Distinctiveness — 15</li>\n<li>Visual/story potential — 15</li>\n<li>Channel fit — 15</li>\n<li>Credibility/evidence — 10</li>\n<li>Series potential — 5</li>\n</ul>\n<div class=\"callout\"><b>Decision rule:</b> 80–100 = strong candidate; 65–79 = improve packaging; below 65 = park or rethink.</div>\n<h3>Copy-and-Use Template</h3>\n<div class=\"template-box\">WORKING IDEA:\n\nTARGET VIEWER:\n\nTHEY WANT / STRUGGLE WITH:\n\nVIDEO PROMISE:\n\nDISTINCTIVE ANGLE:\n\nWHAT I CAN SHOW:\n\nWHY I AM CREDIBLE TO MAKE IT:\n\nPOSSIBLE FOLLOW-UP VIDEO:\n\nSCORE:\nAudience need __/20\nPromise __/20\nDistinctiveness __/15\nVisual/story potential __/15\nChannel fit __/15\nCredibility __/10\nSeries potential __/5\nTOTAL __/100</div>\n", "related": [114]}, {"id": 103, "title": "Title and Thumbnail Development", "category": "Templates", "topic": "Titles & Thumbnails", "type": "Template", "description": "Develop the click promise as one package instead of treating the title and thumbnail as separate decorations.", "tags": ["title", "thumbnail", "packaging"], "content": "\n<h3>Packaging Standard</h3>\n<p>The title and thumbnail should communicate one compelling idea together. They should complement rather than repeat each other word for word.</p>\n<h3>Title Checks</h3>\n<ul>\n<li>Is the subject immediately understandable?</li>\n<li>Is there a clear outcome, surprise, contrast, problem, or stakes?</li>\n<li>Can vague language be made more specific?</li>\n<li>Does the title create an honest reason to click?</li>\n<li>Does it sound natural when spoken aloud?</li>\n</ul>\n<h3>Thumbnail Checks</h3>\n<ul>\n<li>Can the idea be understood at small size?</li>\n<li>Is there one dominant focal point?</li>\n<li>Does it show the transformation, tension, proof, or emotional reaction?</li>\n<li>Is text limited and useful?</li>\n<li>Does it add information the title does not?</li>\n</ul>\n<h3>Development Template</h3>\n<div class=\"template-box\">CORE VIDEO PROMISE:\n\nTITLE DIRECTION 1 — Outcome:\nTITLE:\n\nTITLE DIRECTION 2 — Curiosity:\nTITLE:\n\nTITLE DIRECTION 3 — Contrast / Mistake:\nTITLE:\n\nTHUMBNAIL CONCEPT A:\nMain image:\nVisual contrast:\nText, if any:\n\nTHUMBNAIL CONCEPT B:\nMain image:\nVisual contrast:\nText, if any:\n\nWHY THIS PACKAGE SHOULD EARN THE CLICK:\n\nWHAT THE FIRST 30 SECONDS MUST DELIVER:</div>\n", "related": [110]}, {"id": 104, "title": "Tutorial Video Script", "category": "Templates", "topic": "Storytelling & Scripts", "type": "Template", "description": "A clear tutorial structure that proves the outcome, teaches the process, and prevents mid-video drop-off.", "tags": ["tutorial", "script", "hook"], "content": "\n<h3>Recommended Structure</h3>\n<ul>\n<li><b>0:00–0:15 — Hook:</b> State the outcome and show the finished result.</li>\n<li><b>0:15–0:35 — Why it matters:</b> Name the common frustration and explain what will be different here.</li>\n<li><b>0:35–1:00 — Starting point:</b> Show what is needed and where the viewer begins.</li>\n<li><b>Body — Steps:</b> Demonstrate one action at a time. Explain what, why, and common mistakes.</li>\n<li><b>Progress checks:</b> Show visible movement toward the promised result.</li>\n<li><b>Troubleshooting:</b> Address the most likely failure points.</li>\n<li><b>Final reveal:</b> Compare before and after or expected and actual.</li>\n<li><b>Next step:</b> Lead naturally to the next video or action.</li>\n</ul>\n<div class=\"template-box\">HOOK:\n“In this video, I’ll show you exactly how to ______, even if ______.”\n\nPROOF / PREVIEW:\n[Show the finished outcome immediately.]\n\nWHY THIS MATTERS:\n“Most people get stuck on ______. The usual advice ______ does not solve ______.”\n\nSTARTING POINT:\n“You’ll need ______.”\n\nSTEP 1:\nAction:\nWhy it matters:\nCommon mistake:\nVisual:\n\nSTEP 2:\nAction:\nWhy it matters:\nCommon mistake:\nVisual:\n\nSTEP 3:\nAction:\nWhy it matters:\nAlternative:\nVisual:\n\nRESULT:\n[Show the completed result.]\n\nTROUBLESHOOTING:\nIssue:\nFix:\n\nNEXT STEP:\n“Now that you can ______, the next step is ______.”</div>\n", "related": [105]}, {"id": 105, "title": "Story-Based Video Script", "category": "Templates", "topic": "Storytelling & Scripts", "type": "Template", "description": "A nonfiction story structure using a cold open, escalating complications, stakes, climax, and a meaningful takeaway.", "tags": ["storytelling", "narrative", "tension"], "content": "\n<h3>Story Arc</h3>\n<ul>\n<li><b>Cold open:</b> Drop into the most emotionally charged or surprising moment.</li>\n<li><b>Setup:</b> Establish what you wanted, what was normal, and what was at stake.</li>\n<li><b>Rising action:</b> Add complications, decisions, mistakes, and changing emotions.</li>\n<li><b>Climax:</b> Slow down the decisive moment. Let the viewer experience it.</li>\n<li><b>Resolution:</b> Explain what happened and what changed.</li>\n<li><b>Reflection:</b> Connect the experience to a useful lesson or invitation.</li>\n</ul>\n<h3>Tools for Tension</h3>\n<ul>\n<li>Cliffhangers and open questions</li>\n<li>Withholding the result until the viewer understands the stakes</li>\n<li>Specific sensory detail rather than long exposition</li>\n<li>Dialogue, reactions, and evidence</li>\n<li>Escalating cost, risk, effort, time, or emotional importance</li>\n<li>Surprises and reversals that actually occurred</li>\n</ul>\n<div class=\"template-box\">COLD OPEN:\n[Most intense / surprising moment]\n“And that’s when I realized ______.”\n\nSETUP:\nWhat I wanted:\nWhy it mattered:\nWhat I believed at the time:\nWhat could go wrong:\n\nCOMPLICATION 1:\nWhat happened:\nWhat I decided:\nHow I felt:\n\nCOMPLICATION 2 / ESCALATION:\nWhat became harder:\nWhat was now at stake:\n\nCLIMAX:\nWhere I was:\nWhat happened:\nThe decision / realization:\n\nRESOLUTION:\nWhat happened next:\nWhat changed:\n\nTAKEAWAY:\n“What I learned is ______.”\n\nSERIES BRIDGE:\n“Next, I’m going to test ______.”</div>\n", "related": [104]}, {"id": 106, "title": "Editing for Retention", "category": "Research", "topic": "Editing & Retention", "type": "Guide", "description": "A practical retention framework for removing drag, sustaining progress, and using visual changes with purpose.", "tags": ["editing", "retention", "pacing"], "content": "\n<h3>The Editor’s Job</h3>\n<p>Protect the viewer’s reason to continue. Editing is not merely removing mistakes; it is controlling clarity, momentum, emotion, and payoff.</p>\n<h3>Retention Questions</h3>\n<ul>\n<li>Does each section advance the promise?</li>\n<li>Is the viewer seeing progress or merely hearing explanation?</li>\n<li>Can a sentence, pause, example, or repeated point be removed?</li>\n<li>Does the screen change often enough to support attention without becoming frantic?</li>\n<li>Are open questions answered at satisfying moments?</li>\n<li>Does the strongest proof arrive too late?</li>\n</ul>\n<h3>Useful Editing Tools</h3>\n<ul>\n<li>Cut greetings and context that delay the promise.</li>\n<li>Use B-roll to demonstrate, not merely decorate.</li>\n<li>Change framing when the idea changes.</li>\n<li>Use text or graphics only to clarify a critical point.</li>\n<li>Employ before/after, progress markers, and visual evidence.</li>\n<li>Move a later payoff earlier when the opening lacks proof.</li>\n<li>Leave breathing room during emotional or important moments.</li>\n</ul>\n<div class=\"callout\"><b>Mid-video test:</b> At every major section, ask, “What new reason does the viewer have to stay?”</div>\n", "related": [113]}, {"id": 107, "title": "Filming Plan", "category": "Templates", "topic": "Filming & Production", "type": "Template", "description": "Plan A-roll, demonstrations, B-roll, screen recordings, and evidence before the camera turns on.", "tags": ["filming", "b-roll", "production"], "content": "\n<h3>Plan the Visual Story</h3>\n<div class=\"template-box\">VIDEO:\n\nPRIMARY OUTCOME / PROMISE:\n\nA-ROLL SECTIONS:\n1.\n2.\n3.\n\nMUST-SHOW EVIDENCE:\n1.\n2.\n3.\n\nSCREEN RECORDINGS:\n1.\n2.\n3.\n\nB-ROLL SHOT LIST:\nWide shot:\nMedium shot:\nClose-ups:\nHands / process:\nBefore:\nAfter:\nMistake / problem:\nReaction:\nProgress:\n\nPROPS / FILES / LOCATIONS:\n\nAUDIO SETUP:\n\nLIGHTING SETUP:\n\nCONTINUITY NOTES:\n\nPICKUPS TO RECORD AFTER ROUGH EDIT:</div>\n", "related": [108, 109, 116]}, {"id": 108, "title": "Idea-to-Publish Workflow", "category": "SOPs", "topic": "Workflow", "type": "SOP", "description": "The operating procedure for moving a video from an untested thought to a published learning experiment.", "tags": ["workflow", "production", "sop"], "content": "\n<h3>1. Capture</h3>\n<ul><li>Record the raw idea without inventing unsupported details.</li><li>Identify the possible viewer and desired outcome.</li></ul>\n<h3>2. Validate</h3>\n<ul><li>Score the idea using the validation framework.</li><li>Check channel fit, evidence, visual potential, and differentiation.</li></ul>\n<h3>3. Package</h3>\n<ul><li>Develop title directions and thumbnail concepts.</li><li>Define the promise the opening must fulfill.</li></ul>\n<h3>4. Brief</h3>\n<ul><li>Document audience, promise, takeaway, format, proof, and next-video bridge.</li></ul>\n<h3>5. Script</h3>\n<ul><li>Select tutorial, story, or hybrid structure.</li><li>Build hook, progression, payoff, and CTA.</li></ul>\n<h3>6. Visual Plan</h3>\n<ul><li>Create shot list, screen recordings, B-roll, graphics, and evidence list.</li></ul>\n<h3>7. Film</h3>\n<ul><li>Complete equipment check.</li><li>Record A-roll, demonstrations, evidence, and safety pickups.</li></ul>\n<h3>8. Edit</h3>\n<ul><li>Build the story first.</li><li>Remove drag, add visual clarity, and check retention risks.</li></ul>\n<h3>9. Final Package</h3>\n<ul><li>Confirm title-thumbnail alignment.</li><li>Complete description, chapters, links, end screen, and upload checklist.</li></ul>\n<h3>10. Publish and Analyze</h3>\n<ul><li>Record baseline metrics.</li><li>Review CTR, opening retention, average view duration, traffic, subscribers, and comments.</li></ul>\n<h3>11. Improve</h3>\n<ul><li>Document what worked, what hurt, and one controlled experiment for the next video.</li></ul>\n", "related": [107]}, {"id": 109, "title": "Filming Setup SOP", "category": "SOPs", "topic": "Filming & Production", "type": "SOP", "description": "A repeatable preflight procedure for camera, framing, lighting, sound, and recording readiness.", "tags": ["camera", "microphone", "setup"], "content": "\n<h3>Before Recording</h3>\n<ol>\n<li>Charge camera, microphone transmitters/receiver, lights, and teleprompter device.</li>\n<li>Confirm SD card space and recording format.</li>\n<li>Mount camera securely and set the intended frame.</li>\n<li>Position the lens near eye level.</li>\n<li>Check headroom—do not crop the top of the head.</li>\n<li>Set key light, fill/background light as needed, and remove distracting glare.</li>\n<li>Connect and test the RØDE Wireless PRO system.</li>\n<li>Record a short test and listen with headphones.</li>\n<li>Check clothing noise, room noise, focus, exposure, and white balance.</li>\n<li>Place notes, props, and water within reach.</li>\n<li>Record 10 seconds of room tone.</li>\n<li>Clap or mark sync if recording audio separately.</li>\n</ol>\n<div class=\"callout\"><b>Do not begin the full take until you have watched and listened to the test recording.</b></div>\n", "related": [107, 116]}, {"id": 110, "title": "Thumbnail Review SOP", "category": "SOPs", "topic": "Titles & Thumbnails", "type": "SOP", "description": "A fast quality-control process before a thumbnail is approved for upload or testing.", "tags": ["thumbnail", "review", "quality"], "content": "\n<h3>Review at Small Size</h3>\n<ol>\n<li>Reduce the thumbnail to approximately mobile-feed size.</li>\n<li>Identify the first thing the eye sees.</li>\n<li>State the implied idea in one sentence.</li>\n<li>Check whether the title and thumbnail add different information.</li>\n<li>Remove unnecessary words, objects, and competing focal points.</li>\n<li>Confirm the emotion, transformation, tension, or proof is visible.</li>\n<li>Check face crop, eye line, contrast, and background separation.</li>\n<li>Compare it with surrounding videos in the intended niche.</li>\n<li>Ask whether the package is honest and delivered in the opening.</li>\n</ol>\n<h3>Approval Questions</h3>\n<ul>\n<li>Would the right viewer understand why to click?</li>\n<li>Is it distinctive without becoming confusing?</li>\n<li>Can it survive on a small phone screen?</li>\n<li>Is the most important element unmistakable?</li>\n</ul>\n", "related": [103, 112]}, {"id": 111, "title": "Upload and Publishing Checklist", "category": "Checklists", "topic": "Publishing", "type": "Checklist", "description": "The final quality-control list for packaging, metadata, accessibility, links, and channel continuity.", "tags": ["upload", "publish", "checklist"], "content": "\n<h3>Video and Package</h3>\n<ul>\n<li>Final video watched from beginning to end</li>\n<li>Title and thumbnail communicate one aligned promise</li>\n<li>Opening delivers the promised subject quickly</li>\n<li>Audio, spelling, graphics, and cuts checked</li>\n</ul>\n<h3>YouTube Setup</h3>\n<ul>\n<li>Correct title entered</li>\n<li>Description includes a clear summary and useful links</li>\n<li>Relevant chapters added</li>\n<li>Thumbnail uploaded</li>\n<li>Playlist selected</li>\n<li>Audience setting confirmed</li>\n<li>Subtitles reviewed when available</li>\n<li>Cards and end screen added</li>\n<li>Related next video selected</li>\n<li>Visibility and scheduled time confirmed</li>\n</ul>\n<h3>After Publishing</h3>\n<ul>\n<li>Open public video on phone and desktop</li>\n<li>Test links</li>\n<li>Pin a useful comment or question</li>\n<li>Record publish date and initial metrics in Creator OS</li>\n</ul>\n", "related": []}, {"id": 112, "title": "Post-Publish Review", "category": "Templates", "topic": "Analytics & Improvement", "type": "Template", "description": "A disciplined review that separates packaging, opening, content, audience fit, and next-video learning.", "tags": ["analytics", "review", "improvement"], "content": "\n<h3>Review Windows</h3>\n<p>Use an early check for technical or packaging problems, then a later review when enough data exists. Avoid making emotional conclusions from a tiny sample.</p>\n<div class=\"template-box\">VIDEO:\n\nPUBLISH DATE:\n\nORIGINAL PREDICTION:\nWhat did I expect and why?\n\nPACKAGING:\nImpressions:\nCTR:\nTraffic sources:\nWhat the data suggests:\n\nOPENING:\nFirst 30-second retention:\nLargest early drop:\nPossible cause:\n\nBODY:\nAverage view duration:\nAverage percentage viewed:\nRetention highs:\nRetention drops:\nPossible causes:\n\nAUDIENCE RESPONSE:\nSubscribers gained:\nComments / questions:\nEvidence of audience fit:\n\nWHAT WORKED:\n\nWHAT HURT:\n\nWHAT NOT TO OVERREACT TO:\n\nTOP 3 IMPROVEMENTS:\n1.\n2.\n3.\n\nONE CONTROLLED EXPERIMENT FOR NEXT VIDEO:\n\nLESSON SAVED TO CREATOR OS:</div>\n", "related": [110, 113, 115]}, {"id": 113, "title": "Analytics Diagnosis Framework", "category": "Research", "topic": "Analytics & Improvement", "type": "Guide", "description": "Interpret the combination of impressions, CTR, retention, watch time, traffic, and subscriber response.", "tags": ["analytics", "ctr", "retention"], "content": "\n<h3>Start With the Viewer Journey</h3>\n<ol>\n<li><b>Was it shown?</b> Impressions and traffic sources indicate distribution and audience context.</li>\n<li><b>Did they click?</b> CTR helps evaluate packaging, but must be interpreted with traffic source and scale.</li>\n<li><b>Did the opening deliver?</b> Early retention reveals whether the click promise was confirmed.</li>\n<li><b>Did the body sustain value?</b> Average view duration and the retention graph reveal pacing and relevance.</li>\n<li><b>Did it build the channel?</b> Subscribers, comments, returning viewers, and next-video behavior indicate deeper value.</li>\n</ol>\n<h3>Common Patterns</h3>\n<ul>\n<li><b>Low CTR + strong retention:</b> The video satisfies viewers who click, but packaging may be weak or unclear.</li>\n<li><b>High CTR + weak opening:</b> The package earns clicks, but the beginning delays or contradicts the promise.</li>\n<li><b>Strong opening + mid-video decline:</b> The structure may lose progression, repeat points, or delay payoff.</li>\n<li><b>Views without subscribers:</b> The topic may attract a broad or mismatched audience, or the channel promise is not reinforced.</li>\n<li><b>Low impressions:</b> Do not assume the content is poor; assess topic size, competition, audience history, and initial response.</li>\n</ul>\n<div class=\"callout\"><b>Creator Coach rule:</b> Diagnose before prescribing. Do not change titles, thumbnails, hooks, length, and format all at once.</div>\n", "related": [106, 112, 115]}, {"id": 114, "title": "Creator Coach: Review My Video Idea", "category": "Prompts", "topic": "Ideas", "type": "Prompt", "description": "A structured prompt for testing marketability without allowing AI to invent facts about the project.", "tags": ["prompt", "ideas", "coach"], "content": "\n<h3>Prompt</h3>\n<div class=\"template-box\">Act as my YouTube strategy and product-development coach.\n\nEvaluate the marketability of the video idea below before expanding the story or inventing details.\n\nIDEA:\n[Paste the raw idea.]\n\nKNOWN FACTS:\n[List only what is true.]\n\nTARGET CHANNEL:\nWell, That’s Handy — “Come build an AI-powered life with me.”\n\nTARGET VIEWER:\n[Describe the viewer.]\n\nEvaluate:\n1. Viewer need or curiosity\n2. Clarity of the potential promise\n3. Distinctiveness\n4. Visual and story potential\n5. Fit with the channel\n6. My credibility or evidence\n7. Series potential\n\nGive:\n- a score out of 100\n- the strongest angle\n- the biggest marketability risk\n- three possible title directions\n- three thumbnail concept directions\n- the missing information I should provide next\n\nDo not fill in unknown facts. Clearly label assumptions and questions.</div>\n", "related": [102, 115]}, {"id": 115, "title": "Creator Coach: Diagnose My Analytics", "category": "Prompts", "topic": "Analytics & Improvement", "type": "Prompt", "description": "A coaching prompt that converts uploaded results into evidence-based improvements and a controlled next experiment.", "tags": ["prompt", "analytics", "coaching"], "content": "\n<h3>Prompt</h3>\n<div class=\"template-box\">Act as my YouTube analytics coach.\n\nUse the metrics and context below to diagnose this video. Do not judge a metric in isolation and do not overstate conclusions when the sample is small.\n\nVIDEO:\nTitle:\nThumbnail concept:\nTopic:\nTarget viewer:\nLength:\nPublish date:\n\nRESULTS:\nImpressions:\nCTR:\nFirst 30-second retention:\nAverage view duration:\nAverage percentage viewed:\nSubscribers gained:\nWatch hours:\nTraffic sources:\nKey retention drops or spikes:\nComments / audience feedback:\n\nMY ORIGINAL EXPECTATION:\n\nAnalyze:\n1. What worked\n2. What likely hurt performance\n3. What the evidence does not yet prove\n4. Whether the primary issue was topic, packaging, opening, body, audience fit, or distribution\n5. The three highest-value improvements\n6. One controlled experiment for the next video\n7. The lesson I should save in Creator OS\n\nUse clear, supportive language. Separate evidence, inference, and recommendation.</div>\n", "related": [112, 113, 114]}, {"id": 116, "title": "Equipment Preflight Checklist", "category": "Checklists", "topic": "Filming & Production", "type": "Checklist", "description": "A compact camera, sound, lighting, media, and backup check before every recording session.", "tags": ["equipment", "camera", "audio"], "content": "\n<ul>\n<li>Camera battery charged and spare available</li>\n<li>SD card inserted, formatted, and has enough space</li>\n<li>Lens clean</li>\n<li>Tripod stable</li>\n<li>Frame includes appropriate headroom</li>\n<li>Focus confirmed</li>\n<li>Exposure and white balance checked</li>\n<li>RØDE transmitters and receiver charged</li>\n<li>Microphone positioned correctly</li>\n<li>Audio levels tested and monitored with headphones</li>\n<li>Lights charged / connected and positioned</li>\n<li>Teleprompter working and text loaded</li>\n<li>Phone silenced</li>\n<li>Room noise minimized</li>\n<li>Test clip watched and heard</li>\n<li>External drive / backup plan ready</li>\n</ul>\n", "related": [107, 109]}, {"id": 117, "title": "Serial Content and Series Planning", "category": "Research", "topic": "Strategy", "type": "Guide", "description": "Use episodic accessibility and serialized progress to build both discoverability and viewer loyalty.", "tags": ["series", "serial", "audience"], "content": "\n<h3>Episodic vs. Serial</h3>\n<p>An episodic video stands alone and welcomes a new viewer. A serial video advances an ongoing journey and rewards returning viewers. The strongest channel strategy can combine both.</p>\n<h3>Creator OS Application</h3>\n<ul>\n<li>Each video should offer a complete, useful outcome to a first-time viewer.</li>\n<li>The Command Center provides the serial layer: progress, experiments, goals, setbacks, and improvements.</li>\n<li>End with a clear next question or upcoming experiment.</li>\n<li>Use recurring language and visuals so viewers recognize the journey.</li>\n<li>Do not require extensive backstory; briefly orient new viewers.</li>\n</ul>\n<div class=\"callout\"><b>Series premise:</b> Watch Carolynn use AI to build a channel, a business, and a more capable life—one practical experiment at a time.</div>\n", "related": [101]}, {"id": 118, "title": "Creator OS Video Brief", "category": "Templates", "topic": "Workflow", "type": "Interactive Template", "description": "Build the strategic brief connecting audience, promise, package, proof, structure, and next action before scripting.", "tags": ["brief", "strategy", "interactive"], "related": [102, 103, 104, 105], "content": "\n<h3>Purpose</h3>\n<p>Use this before scripting. A strong brief prevents a good idea from turning into a vague video.</p>\n<h3>Brief Components</h3>\n<ul>\n<li>Target viewer</li>\n<li>Viewer problem, desire, or curiosity</li>\n<li>Single video promise</li>\n<li>Distinctive angle</li>\n<li>Evidence or demonstration</li>\n<li>Title and thumbnail direction</li>\n<li>Story or tutorial structure</li>\n<li>Next-video bridge</li>\n</ul>\n<div class=\"callout\"><b>Interactive version:</b> Use the Build Brief button in the Creator OS to complete and save your brief.</div>\n"}];
