h+='<div class="resource-summary"><div class="summary-card"><small>TOTAL RESOURCES</small><strong>'+total+'</strong></div><div class="summary-card"><small>RESEARCH GUIDES</small><strong>'+guides+'</strong></div><div class="summary-card"><small>TEMPLATES</small><strong>'+templates+'</strong></div><div class="summary-card"><small>SOPS</small><strong>'+sops+'</strong></div></div>';
h+='<div class="resource-toolbar"><input id="resourceSearch" placeholder="Search titles, thumbnails, retention, analytics..."><select id="resourceCategory">'+cats.map(function(c){return '<option '+(c===selected?'selected':'')+'>'+c+'</option>'}).join('')+'</select><select id="resourceTopic">'+topics.map(function(t){return '<option>'+t+'</option>'}).join('')+'</select></div>';
