function updateLibraryGrid(){
var search=(el('resourceSearch')?el('resourceSearch').value:'').toLowerCase();
var category=el('resourceCategory')?el('resourceCategory').value:'All';
var topic=el('resourceTopic')?el('resourceTopic').value:'All';
var items=library.filter(function(r){
var temp=document.createElement('div');
temp.innerHTML=r.content||'';
var plain=temp.innerText||'';
var hay=(r.title+' '+r.description+' '+r.category+' '+r.topic+' '+r.tags.join(' ')+' '+plain).toLowerCase();
return (!search||hay.indexOf(search)>=0)&&(category==='All'||r.category===category)&&(topic==='All'||r.topic===topic);
});
el('libraryGrid').innerHTML=items.length?items.map(function(r){
return '<article class="library-card"><div class="eyebrow">'+esc(r.category)+' · '+esc(r.type)+'</div><h3>'+esc(r.title)+'</h3><p>'+esc(r.description)+'</p><div class="tags">'+r.tags.map(function(t){return '<span class="tag-chip">'+esc(t)+'</span>'}).join('')+'</div><button class="gold" data-resource-id="'+r.id+'">Open Resource</button></article>';
}).join(''):'<article class="card"><h3>No matching resources</h3><p>Try a broader search or select All.</p></article>';
}
